import{iniciarSPA}from"./spa.js";import{validarFormulario}from"./formValidation.js";document.addEventListener("DOMContentLoaded",()=>{iniciarSPA();if(window.location.pathname.includes("cadastro.html")){validarFormulario()}const t=document.getElementById("toggle-dark-mode"),e=document.body;if(t){const o="true"===localStorage.getItem("modoEscuro");o&&(e.classList.add("dark-mode"),t.textContent="☀️"),t.addEventListener("click",()=>{e.classList.toggle("dark-mode");const o=e.classList.contains("dark-mode");localStorage.setItem("modoEscuro",o),t.textContent=o?"☀️":"🌙"})}});
